      border-radius: 4px;
    }
    .task.completed span {
      text-decoration: line-through;
      color: #888;
    }
    .task button {
      margin-left: 10px;
    }
    #categories {
      display: flex;
      gap: 15px;
      flex-wrap: wrap;
    }
    .category {
      padding: 10px 15px;
      background: #007bff;
      color: white;
      border-radius: 4px;
      cursor: pointer;
    }
    .category.active {
      background: #0056b3;
    }
  </style>
</head>
<body>
  <div id="app">
    <h1>Todo List by Interest</h1>
    <div id="category-section">
      <h2>Categories</h2>
      <div id="categories"></div>
    </div>
    <div id="task-section">
      <h2>Add New Task</h2>
      <form id="task-form">
        <label for="task-title">Task Title:</label>
        <input type="text" id="task-title" required />
        <label for="task-description">Description:</label>
        <textarea id="task-description" rows="3"></textarea>
        <label for="task-category">Category:</label>
        <select id="task-category"></select>
        <button type="submit">Add Task</button>
        <button type="button" id="add-category-btn">Add New Category</button>
      </form>
      <div id="tasks"></div>
    </div>
  </div>

  <script>
    let categories = [];

    // Load from localStorage
    function loadTasks() {
      const saved = localStorage.getItem('todoCategories');
      if (saved) {
        categories = JSON.parse(saved);
      } else {
        // Initialize default categories
        categories = [
          { id: 1, name: 'Fitness', tasks: [] },
          { id: 2, name: 'Reading', tasks: [] },
          { id: 3, name: 'Work', tasks: [] },
        ];
        saveTasks();
      }
    }

    // Save to localStorage
    function saveTasks() {
      localStorage.setItem('todoCategories', JSON.stringify(categories));
    }

    // Populate category dropdown
    function populateCategoryDropdown() {
      const select = document.getElementById('task-category');
      select.innerHTML = '';
      categories.forEach(category => {
        const option = document.createElement('option');
        option.value = category.id;
        option.textContent = category.name;
        select.appendChild(option);
      });
    }

    // Render categories
    function renderCategories() {
      const container = document.getElementById('categories');
      container.innerHTML = '';
      categories.forEach(category => {
        const btn = document.createElement('div');
        btn.className = 'category';
        btn.textContent = category.name;
        btn.onclick = () => showTasks(category.id);
        container.appendChild(btn);
      });
    }

    // Show tasks for a specific category
    function showTasks(categoryId) {
      const tasksDiv = document.getElementById('tasks');
      tasksDiv.innerHTML = '';
      const category = categories.find(c => c.id === categoryId);
      if (category) {
        const categoryHeader = document.createElement('h3');
        categoryHeader.textContent = category.name;
        tasksDiv.appendChild(categoryHeader);
        category.tasks.forEach(task => {
          const taskDiv = document.createElement('div');
          taskDiv.className = 'task' + (task.completed ? ' completed' : '');
          taskDiv.innerHTML = `
            <span>${task.title}</span>
            <div>
              <button onclick="toggleTask(${task.id})">Mark as Done</button>
              <button onclick="deleteTask(${task.id}, ${categoryId})">Delete</button>
            </div>
          `;
          tasksDiv.appendChild(taskDiv);
        });
      }
    }

    // Toggle task completion
    function toggleTask(taskId) {
      const task = categories.flatMap(c => c.tasks).find(t => t.id === taskId);
      if (task) {
        task.completed = !task.completed;
        saveTasks();
        renderCategories();
        showTasks(task.categoryId);
      }
    }

    // Delete a task
    function deleteTask(taskId, categoryId) {
      const category = categories.find(c => c.id === categoryId);
      if (category) {
        category.tasks = category.tasks.filter(t => t.id !== taskId);
        saveTasks();
        renderCategories();
        showTasks(categoryId);
      }
    }

    // Add new category
    document.getElementById('add-category-btn').addEventListener('click', () => {
      const categoryName = prompt('Enter new category name:');
      if (categoryName) {
        const newCategory = {
          id: categories.length + 1,
          name: categoryName,
          tasks: []
        };
        categories.push(newCategory);
        saveTasks();
        renderCategories();
        populateCategoryDropdown();
      }
    });

    // Add new task
    document.getElementById('task-form').addEventListener('submit', function(e) {
      e.preventDefault();
      const title = document.getElementById('task-title').value.trim();
      const description = document.getElementById('task-description').value.trim();
      const categoryId = parseInt(document.getElementById('task-category').value);
      const category = categories.find(c => c.id === categoryId);

      if (!title) return;

      const newTask = {
        id: Date.now(),
        title: title,
        description: description,
        completed: false,
        categoryId: categoryId
      };

      category.tasks.push(newTask);
      saveTasks();
      renderCategories();
      showTasks(categoryId);

      // Clear form
      document.getElementById('task-title').value = '';
      document.getElementById('task-description').value = '';
    });

    // Initialize app
    loadTasks();
    renderCategories();
    populateCategoryDropdown();
  </script>
</body>
</html>
